package com.nigson.commerce.pricing;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import java.sql.*;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Family serialization preserves immutable published records and monotonically assigned revisions. */
public final class JdbcPriceBookRepository implements PriceBookRepository {
 private final JdbcTemplate jdbc;private final Clock clock;public JdbcPriceBookRepository(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
 private void family(String code){jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(r,n)->1,"price-book:"+code);}
 private int currency(String code){var values=jdbc.query("SELECT minor_unit FROM commerce.currency WHERE code=? AND active FOR SHARE",(r,n)->r.getInt(1),code);if(values.size()!=1||values.getFirst()<0||values.getFirst()>4||code.equals("NGN")&&values.getFirst()!=2)throw PricingValues.rule();return values.getFirst();}
 private void validate(PricingValues.Input input){int scale=currency(input.currency());if(input.entries().isEmpty()||input.entries().size()>500||!Set.of("RETAIL","DISTRIBUTOR").contains(input.segment())||input.effectiveFrom()==null||input.effectiveUntil()!=null&&!input.effectiveUntil().isAfter(input.effectiveFrom()))throw PricingValues.rule();var keys=new HashSet<String>();for(var entry:input.entries().stream().sorted(Comparator.comparing(e->e.skuId().toString())).toList()){var values=jdbc.query("SELECT s.quantity_scale FROM commerce.sku s JOIN commerce.product p ON p.id=s.product_id WHERE s.id=? AND s.active AND s.deleted_at IS NULL AND p.deleted_at IS NULL FOR SHARE OF p,s",(r,n)->r.getInt(1),entry.skuId());if(values.size()!=1)throw PricingValues.rule();BigDecimal qty=PricingValues.quantity(entry.minimumQuantity(),values.getFirst());PricingValues.minor(entry.unitAmount(),scale);if(!keys.add(entry.skuId()+":"+PricingValues.decimal(qty)))throw PricingValues.rule();}}
 private PricingValues.Book row(ResultSet r)throws SQLException{return new PricingValues.Book(r.getObject("id",UUID.class),r.getString("code"),r.getLong("revision"),r.getString("currency_code"),r.getString("segment"),r.getTimestamp("effective_from").toInstant(),r.getTimestamp("effective_until")==null?null:r.getTimestamp("effective_until").toInstant(),r.getBoolean("active"),List.of(),r.getLong("version"));}
 private PricingValues.Book withEntries(PricingValues.Book book,List<PricingValues.Entry> entries){return new PricingValues.Book(book.id(),book.code(),book.revision(),book.currency(),book.segment(),book.effectiveFrom(),book.effectiveUntil(),book.active(),List.copyOf(entries),book.version());}
 public PricingValues.Book find(UUID id,boolean lock){var rows=jdbc.query("SELECT * FROM commerce.price_book WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->row(r),id);if(rows.isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);var entries=jdbc.query("SELECT sku_id,minimum_quantity,unit_amount FROM commerce.price_entry WHERE price_book_id=? ORDER BY sku_id,minimum_quantity LIMIT 501",(r,n)->new PricingValues.Entry(r.getObject(1,UUID.class),PricingValues.decimal(r.getBigDecimal(2)),PricingValues.decimal(r.getBigDecimal(3))),id);if(entries.size()>500)throw PricingValues.rule();return withEntries(rows.getFirst(),entries);}
 private PricingValues.Book insert(PricingValues.Input input,String code,long revision,String actor){validate(input);UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.price_book(id,created_by,updated_by,code,currency_code,segment,revision,effective_from,effective_until,active) VALUES (?,?,?,?,?,?,?,?,?,false)",id,actor,actor,code,input.currency(),input.segment(),revision,Timestamp.from(input.effectiveFrom()),input.effectiveUntil()==null?null:Timestamp.from(input.effectiveUntil()));for(var e:input.entries())jdbc.update("INSERT INTO commerce.price_entry(id,created_by,updated_by,price_book_id,sku_id,minimum_quantity,unit_amount) VALUES (?,?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor,actor,id,e.skuId(),new BigDecimal(e.minimumQuantity()),new BigDecimal(e.unitAmount()));return find(id,false);}
 public PricingValues.Book create(PricingValues.Input value,String actor){if(value.code()==null||value.code().isBlank()||value.code().length()>60||value.code().codePoints().anyMatch(c->Character.isISOControl(c)||Character.getType(c)==Character.FORMAT))throw ApiValues.invalid();family(value.code());if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.price_book WHERE code=?)",Boolean.class,value.code())))throw new Problem.Failure(ProblemCode.CONFLICT);return insert(value,value.code(),1,actor);}
 public PricingValues.Book revise(UUID source,long expected,PricingValues.Input value,String actor){var initial=find(source,false);family(initial.code());var before=find(source,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);long latest=jdbc.queryForObject("SELECT max(revision) FROM commerce.price_book WHERE code=?",Long.class,before.code());if(before.revision()!=latest)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(latest==Long.MAX_VALUE||!before.currency().equals(value.currency())||!before.segment().equals(value.segment())||!value.effectiveFrom().isAfter(before.effectiveFrom())||before.active()&&(before.effectiveUntil()==null||value.effectiveFrom().isBefore(before.effectiveUntil())))throw PricingValues.rule();return insert(value,before.code(),latest+1,actor);}
 public PricingValues.Book activate(UUID id,long expected,String actor){var initial=find(id,false);family(initial.code());var before=find(id,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(before.active())throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(before.version()==Long.MAX_VALUE||before.effectiveUntil()!=null&&!clock.instant().isBefore(before.effectiveUntil()))throw PricingValues.rule();validate(new PricingValues.Input(before.code(),before.currency(),before.segment(),before.effectiveFrom(),before.effectiveUntil(),before.entries()));boolean overlap=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.price_book WHERE code=? AND active AND id<>? AND (effective_until IS NULL OR effective_until>?) AND (?::timestamptz IS NULL OR effective_from<?))",Boolean.class,before.code(),id,Timestamp.from(before.effectiveFrom()),before.effectiveUntil()==null?null:Timestamp.from(before.effectiveUntil()),before.effectiveUntil()==null?null:Timestamp.from(before.effectiveUntil())));if(overlap)throw PricingValues.rule();jdbc.update("UPDATE commerce.price_book SET active=true,version=version+1,updated_by=?,updated_at=? WHERE id=?",actor,Timestamp.from(clock.instant()),id);return find(id,false);}
 public PricingValues.Page list(PricingValues.Query q){String where=" WHERE (?::text IS NULL OR segment=?) AND (?::text IS NULL OR currency_code=?)";Object[] args={q.segment(),q.segment(),q.currency(),q.currency()};long count=jdbc.queryForObject("SELECT count(*) FROM commerce.price_book"+where,Long.class,args);String column=switch(q.sort().split(",")[0]){case "code"->"code";case "revision"->"revision";case "effectiveFrom"->"effective_from";default->throw ApiValues.invalid();};var params=new ArrayList<Object>(Arrays.asList(args));params.add(q.size());params.add((long)q.page()*q.size());var books=jdbc.query("SELECT * FROM commerce.price_book"+where+" ORDER BY "+column+(q.sort().endsWith(",desc")?" DESC":" ASC")+",id LIMIT ? OFFSET ?",(r,n)->row(r),params.toArray());if(books.isEmpty())return new PricingValues.Page(List.of(),q.page(),q.size(),count,(count+q.size()-1)/q.size());var entries=new HashMap<UUID,List<PricingValues.Entry>>();String marks=String.join(",",Collections.nCopies(books.size(),"?"));jdbc.query("SELECT price_book_id,sku_id,minimum_quantity,unit_amount FROM commerce.price_entry WHERE price_book_id IN ("+marks+") ORDER BY price_book_id,sku_id,minimum_quantity LIMIT "+(501*books.size()),r->{UUID id=r.getObject(1,UUID.class);var list=entries.computeIfAbsent(id,k->new ArrayList<>());if(list.size()>=500)throw PricingValues.rule();list.add(new PricingValues.Entry(r.getObject(2,UUID.class),PricingValues.decimal(r.getBigDecimal(3)),PricingValues.decimal(r.getBigDecimal(4))));},books.stream().map(PricingValues.Book::id).toArray());return new PricingValues.Page(books.stream().map(b->withEntries(b,entries.getOrDefault(b.id(),List.of()))).toList(),q.page(),q.size(),count,(count+q.size()-1)/q.size());}
}
